import zipfile
import xml.etree.ElementTree as ET
import re

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    letters = re.match(r"[A-Z]+", ref).group()
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1

path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("ZIP entries:", names)

    shared = []
    if "xl/sharedStrings.xml" in names:
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    rels_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {}
    for rel in rels_root.findall("{http://schemas.openxmlformats.org/package/2006/relationships}Relationship"):
        rel_map[rel.get("Id")] = rel.get("Target")

    for sheet_el in wb_root.find("m:sheets", NS):
        name = sheet_el.get("name")
        rid = sheet_el.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        target = rel_map.get(rid, "")
        if not target.startswith("xl/"):
            target = "xl/" + target.lstrip("/")
        print(f"\n--- Sheet: {name} (target {target}) ---")
        sheet_root = ET.fromstring(z.read(target))
        for row in sheet_root.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row"):
            vals = {}
            for c in row.findall("m:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v_el = c.find("m:v", NS)
                if v_el is None or v_el.text is None:
                    continue
                raw = v_el.text
                if t == "s":
                    val = shared[int(raw)]
                elif t == "inlineStr":
                    is_el = c.find("m:is", NS)
                    val = "".join(x.text or "" for x in is_el.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                elif t == "b":
                    val = raw == "1"
                elif t == "str":
                    val = raw
                else:
                    val = raw
                vals[ref] = val
            if vals:
                print(sorted(vals.items(), key=lambda kv: (int(re.match(r"[A-Z]+", kv[0]).end() and 0), col_to_idx(kv[0]))))

